12	
13	    /** Minimum number of digits allowed after the leading {@code '+'} in E.164. */
14	    private static final int MIN_DIGITS = 8;
15	
16	    /** Maximum number of digits allowed after the leading {@code '+'} in E.164. */
17	    private static final int MAX_DIGITS = 15;
18	
